'use strict';
(()=>{
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={book:'<path d="M12 5v16M3 4c4-1 6 0 9 2 3-2 5-3 9-2v15c-4-1-6 0-9 2-3-2-5-3-9-2z"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',file:'<path d="M5 3h9l5 5v13H5zM14 3v5h5M9 12h6m-6 4h6"/>',arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>',external:'<path d="M14 3h7v7M21 3 10 14M10 3H3v18h18v-7"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0z"/><circle cx="12" cy="10" r="2.5"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',logout:'<path d="M9 4H3v16h6m5-12 4 4-4 4m-5-4h12"/>',print:'<path d="M6 8V3h12v5M6 17H3V8h18v9h-3M6 14h12v7H6z"/>',phone:'<rect x="6" y="2" width="12" height="20" rx="2"/><path d="M10 18h4"/>',check:'<path d="m5 12 4 4L20 5"/>'};
const icon=n=>`<svg aria-hidden="true" viewBox="0 0 24 24">${icons[n]||icons.file}</svg>`;
const groups=['Aushang & Bekanntmachung','Weitere Arbeitsgesetze','Arbeitsschutz & Prävention','Branchenspezifische Texte','BGN · Unfallverhütung'];
let bvData=null,bvLoading=false,bvTrash=false,bvToken=0;
let noticeState=null,noticeLoading=false,noticeToken=0,noticeDirty=false;
let topics=[],portalInfo=null,query='',category='',letter='',docState=null,docTrash=false,docLoading=false,documentRequestToken=0,lastCollectionView='aushang';
let access=null,deviceError=null,deviceBusy=false,deviceList=[],createdDevice=null;
const device=window.AushangDevice;
let account=null,catalog=[],favorites=[],meta=null,view='aushang',authView='login',signupDraft=null,recoveryCode='',readerId='',readerToken=0,large=false,installPrompt=null,saving=false,toastTimer;
const brand=()=>'<a href="#home" class="brand"><span class="brand-sign">§</span>aushang.</a>';
const date=v=>{const d=new Date(v);return Number.isNaN(d.getTime())?'–':d.toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit',year:'numeric'});};
async function api(path,method='GET',data,retried=false){const r=await fetch(path,{method,credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined,cache:'no-store'});const result=await r.json().catch(()=>({error:'Der Dienst ist nicht erreichbar.'}));if(!r.ok){if(r.status===401&&device.activeId&&!retried){await device.unlock();return api(path,method,data,true);}if(r.status===401&&account){account=null;access=null;clearPortalState();authView='login';render();}throw Error(result.error||'Die Anfrage konnte nicht abgeschlossen werden.');}return result;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function updateDate(){if(!meta){$('#update-date').textContent='Quellenstand vorübergehend nicht verfügbar';return;}const stale=(Date.now()-new Date(meta.lastSuccessfulCheck).getTime())>40*86400000;$('#update-date').textContent=`Letzte vollständige Aktualisierung: ${date(meta.lastSuccessfulCheck)}`;$('#update-policy').textContent=meta.lastAttemptStatus==='failed'?'Letzter Stand aktiv · neue Prüfung ausstehend':stale?'Neue Quellenprüfung ausstehend':'Monatlich · jeweils am 1.';$('#update-bar').classList.toggle('warning',stale||meta.lastAttemptStatus==='failed');}
function authFields(){if(authView==='recover')return `<h2>Zugang wiederherstellen.</h2><p class="form-intro">Mit Ihrem Benutzernamen und dem bei der Registrierung gesicherten Wiederherstellungscode.</p><form id="recover-form"><label class="field">Benutzername<input name="username" autocomplete="username" required maxlength="48"></label><label class="field">Wiederherstellungscode<input name="recoveryCode" autocomplete="off" required minlength="64" maxlength="64" spellcheck="false"></label><label class="field">Neues Passwort<input name="newPassword" type="password" autocomplete="new-password" required minlength="15" maxlength="128"><small>15 bis 128 Zeichen. Eine lange Passphrase ist gut merkbar.</small></label><label class="field">Neues Passwort wiederholen<input name="confirmPassword" type="password" autocomplete="new-password" required minlength="15" maxlength="128"></label><div class="form-error" id="form-error" role="alert"></div><button class="button primary" type="submit">Neues Passwort festlegen ${icon('arrow')}</button></form><p class="auth-note"><button class="text-button" data-auth="login">Zur Anmeldung zurück</button></p>`;
 if(authView==='register'&&signupDraft)return `<div class="registration-progress"><span>01 · Zugang</span><i></i><span class="current">02 · Standort</span></div><h2>Ihr verbindlicher Standort.</h2><p class="form-intro">Dieser Zugang gehört ausschließlich zu dem hier angegebenen Werk und dieser Adresse.</p><form id="register-site-form"><label class="field">Firma<input name="company" autocomplete="organization" required maxlength="140" placeholder="Unternehmensname"></label><label class="field">Werk / Standort<input name="work" required maxlength="140" placeholder="z. B. Werk Süd oder Hauptstandort"></label><div class="address-grid"><label class="field">Straße<input name="street" autocomplete="address-line1" required maxlength="140"></label><label class="field">Hausnummer<input name="houseNumber" required maxlength="20"></label></div><div class="address-grid"><label class="field">Ort<input name="city" autocomplete="address-level2" required maxlength="140"></label><label class="field">PLZ<input name="postalCode" autocomplete="postal-code" inputmode="numeric" required pattern="[0-9]{5}" maxlength="5"></label></div><label class="field">Land<input name="country" value="Deutschland" readonly required></label><label class="check-label"><input name="businessOnly" type="checkbox" required>Ich registriere diesen Zugang für ein Unternehmen und bin hierzu berechtigt.</label><label class="check-label" style="margin-top:12px"><input name="acceptSiteScope" type="checkbox" required>Ich bestätige die angegebenen Standortdaten und den <button type="button" class="text-button" data-page="terms">standortgebundenen Nutzungsumfang</button>.</label><div class="form-error" id="form-error" role="alert"></div><button class="button primary" type="submit">Standortzugang anlegen ${icon('arrow')}</button></form><p class="auth-note">Unverbindliche Zugangsanfrage. Freischaltung nach gesonderter Vereinbarung und Zahlungsbestätigung; keine automatische Abbuchung. <button class="text-button" data-page="privacy">Datenschutzhinweise</button></p><button class="text-button" data-action="signup-back">← Zurück zu den Zugangsdaten</button>`;
 if(authView==='register')return `<div class="registration-progress"><span class="current">01 · Zugang</span><i></i><span>02 · Standort</span></div><h2>Ein eigener Zugang.</h2><p class="form-intro">Legen Sie zuerst Ihren Benutzernamen und Ihr Passwort fest. Danach erfassen Sie Werk und Adresse.</p><form id="register-account-form"><label class="field">Benutzername<input name="username" autocomplete="username" required minlength="3" maxlength="48" pattern="[A-Za-z0-9][A-Za-z0-9._-]{2,47}" placeholder="z. B. firma-werk-01"><small>3–48 Zeichen: Buchstaben a–z, Ziffern, Punkt, Bindestrich oder Unterstrich.</small></label><label class="field">Passwort<input name="password" type="password" autocomplete="new-password" required minlength="15" maxlength="128"><small>15 bis 128 Zeichen. Bitte kein bereits anderweitig verwendetes Passwort.</small></label><label class="field">Passwort wiederholen<input name="confirmPassword" type="password" autocomplete="new-password" required minlength="15" maxlength="128"></label><div class="form-error" id="form-error" role="alert"></div><button class="button primary" type="submit">Weiter zum Standort ${icon('arrow')}</button></form><p class="auth-note">Es werden Benutzername, geschützte Zugangsdaten und der verbindliche Unternehmensstandort benötigt. <button class="text-button" data-page="privacy">Datenschutzhinweise</button></p>`;
 return `<h2>Anmelden</h2><p class="form-intro">Mit Ihrem freigeschalteten Standortzugang.</p><form id="login-form"><label class="field">Benutzername<input name="username" autocomplete="username" autocapitalize="none" autocorrect="off" spellcheck="false" required maxlength="48" placeholder="Ihr Benutzername"></label><label class="field">Passwort<span class="password-field"><input id="login-password" name="password" type="password" autocomplete="current-password" required maxlength="128" placeholder="Ihr Passwort"><button type="button" data-action="show-password" aria-label="Passwort anzeigen">Anzeigen</button></span></label><button class="text-button forgot-link" type="button" data-auth="recover">Passwort vergessen?</button><label class="check-label device-choice"><input name="setupDevice" type="checkbox" checked>Diesen Firmencomputer dauerhaft einrichten</label><div class="form-error" id="form-error" role="alert"></div><button class="button primary full" type="submit" value="portal">Anmelden ${icon('arrow')}</button></form><p class="auth-note">Die Gerätefreigabe gilt nur für dieses Browserprofil. Auf einem fremden Gerät bitte nicht aktivieren.</p>`;
}
function sideNav(){return `<aside class="account-sidebar">${brand()}<div class="nav-label">IHR GESETZESPORTAL</div><nav><button class="nav-item ${view==='collection'?'active':''}" data-view="collection">${icon('book')}Alle Gesetze<span class="nav-count">${catalog.length}</span></button><button class="nav-item ${view==='favorites'?'active':''}" data-view="favorites">${icon('bookmark')}Meine Favoriten<span class="nav-count">${favorites.length}</span></button><button class="nav-item ${view==='account'?'active':''}" data-view="account">${icon('user')}Mein Zugang</button></nav><div class="sidebar-bottom"><div class="source-note">${icon('shield')}<strong>Offizielle Gesetzestexte.</strong><p>Gesetze im Internet<br>und Vorschriften der BGN.</p></div><button class="nav-item" data-action="logout">${icon('logout')}${device.activeId?'Zugang schließen':'Abmelden'}</button></div></aside>`;}
function card(law,index){return `<button class="book-card" data-law="${law.id}" aria-label="${esc(law.title)} lesen"><span class="book-spine ${law.color||'green'}" aria-hidden="true"></span><span class="book-copy"><span class="book-abbr">${String(index+1).padStart(2,'0')} / ${esc(law.short)}</span><h3>${esc(law.title)}</h3><span class="book-bottom"><span>${law.localPdf?'PDF lesen':'Gesetz lesen'}</span>${law.select?'<span class="book-kind">Auszug</span>':''}${law.conditional?'<span class="book-kind">Bedingt</span>':''}${icon('arrow')}</span></span></button>`;}
function accountPage(){return `<span class="eyebrow">STANDORTGEBUNDENER ZUGANG</span><h1 class="page-title">Mein Zugang.</h1><p class="page-sub">Die Standortzuordnung ist verbindlich und wird serverseitig gespeichert.</p><section class="form-panel"><h2>Ihr registrierter Standort</h2><dl class="account-detail">${[['Benutzername',account.username],['Firma',account.company],['Werk / Standort',account.work],['Adresse',`${account.street} ${account.houseNumber}, ${account.postalCode} ${account.city}`],['Land',account.country],['Nutzungsstatus',access?.canRead?(account.licensePermanent===1?'Unbefristet freigeschaltet':'Freigeschaltet bis '+date(account.licenseValidUntil*1000)):'Freischaltung ausstehend']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><p class="legal-note">Die Zuordnung gilt für den oben angegebenen Standort. Korrekturen und weitere Standorte werden über den Anbieter vereinbart. <a href="mailto:Umit.durmaz@gmx.de">Anbieter kontaktieren</a></p></section>${devicePanel()}${access?.kind==='device'?'<section class="form-panel"><h2>Gerätezugang</h2><p>Dieser Browser öffnet die Sammlung ohne erneute Passworteingabe. Die Zugangsverwaltung bleibt mit dem Passwort geschützt.</p><a class="button" href="/#anmelden">Zugang verwalten</a></section>':`<form id="password-form" class="form-panel"><h2>Passwort ändern</h2><div class="form-grid"><label class="field">Aktuelles Passwort<input name="currentPassword" type="password" autocomplete="current-password" required maxlength="128"></label><label class="field">Neues Passwort<input name="newPassword" type="password" autocomplete="new-password" required minlength="15" maxlength="128"></label><label class="field">Neues Passwort wiederholen<input name="confirmPassword" type="password" autocomplete="new-password" required minlength="15" maxlength="128"></label></div><div class="form-error" id="form-error" role="alert"></div><div class="form-buttons"><button class="button primary" type="submit">Passwort ändern</button><button class="button" type="button" data-action="logout">Abmelden</button></div><p class="legal-note">Bei einer Passwortänderung werden bisherige Sitzungen und Gerätefreigaben widerrufen.</p></form>`}`;}
function recoveryPage(){return publicHeader()+`<main id="main" class="auth-layout"><section class="auth-pitch"><span class="eyebrow">ZUGANG ERSTELLT</span><h1>Ihr Standort.<br><em>Ihr Gesetzesbuch.</em></h1><p>Bevor Sie starten, sichern Sie bitte den einmaligen Wiederherstellungscode für diesen Zugang.</p></section><section class="auth-card"><h2>Wiederherstellungscode sichern.</h2><p>Es wird keine E-Mail-Adresse zur Anmeldung benötigt. Mit diesem Code können Sie Ihr Passwort zurücksetzen. Der Code wird nach dem Schließen nicht erneut angezeigt.</p><code class="recovery-code">${esc(recoveryCode)}</code><div class="recovery-actions"><button class="button" data-action="copy-code">Code kopieren</button><button class="button" data-action="download-code">Code herunterladen</button></div><p class="auth-note">Sicher aufbewahren und nicht mit dem Standort-Lesezugang aushängen.</p><label class="check-label"><input id="code-saved" type="checkbox">Ich habe den Wiederherstellungscode sicher gespeichert.</label><button class="button primary" data-action="finish-recovery">${access?.canRead?'Geräte-Link erstellen':'Zur Zugangsanfrage'} ${icon('arrow')}</button></section></main>`;}
async function hydrateAccount(){const previousId=account?.id;const r=await api('/api/me');account=r.account;access=r.access;meta=r.meta;if(previousId!==account?.id||!access?.canRead)clearPortalState();favorites=r.favorites||[];if(device.activeId&&access?.deviceId!==device.activeId){account=null;access=null;clearPortalState();throw Error('Der Gerätezugang konnte nicht eindeutig zugeordnet werden.');}if(account&&access?.canRead&&!catalog.length){const id=account.id,p=await api('/api/catalog');if(account?.id!==id)return;catalog=p.catalog;topics=p.topics;portalInfo=p;noticeState={...p.siteNotices,accountId:id};}if(account&&access?.canRead&&access?.kind==='password')await loadDevices();else deviceList=[];if(!device.activeId&&location.hash==='#anmelden'&&access?.kind==='device'){account=null;access=null;clearPortalState();authView='login';}render();}
async function loadReader(){const token=++readerToken,l=catalog.find(x=>x.id===readerId);if(!l)return;const ordered=catalog.filter(x=>x.hosted).sort(sortTitle);const position=ordered.indexOf(l);const end=`<div class="reader-end">${position?`<button class="button" data-law="${ordered[position-1].id}">← ${esc(ordered[position-1].short)}</button>`:'<span></span>'}${position<ordered.length-1?`<button class="button" data-law="${ordered[position+1].id}">${esc(ordered[position+1].short)} ${icon('arrow')}</button>`:''}</div>`;
 if(l.localPdf){$('#reader-content').innerHTML=`<div class="reader-source"><strong>Original-PDF der BGN</strong> · Sammlung geprüft: ${date(meta.lastSuccessfulCheck)}<br><a href="${l.url}" target="_blank" rel="noopener noreferrer">Quelle bei der BGN</a></div><a class="button primary" href="/api/pdf/${l.id}" target="_blank" rel="noopener noreferrer">PDF in eigenem Fenster öffnen ${icon('external')}</a><p class="legal-note">Wenn der Browser keine eingebetteten PDFs unterstützt, bitte den Link oben verwenden.</p><object class="pdf-frame" data="/api/pdf/${l.id}" type="application/pdf" aria-label="${esc(l.title)}"><p>Bitte die PDF über den Link oben öffnen.</p></object>${end}`;return;}
 try{const p=await api(`/api/texts/${l.id}`);if(token!==readerToken||view!=='reader'||!$('#reader-content'))return;const source=p.source;$('#reader-content').innerHTML=`<div class="reader-source"><strong>${source.excerpt?'Gesetzesauszug: '+esc(source.excerpt.join(', ')):'Gesetzestext aus der offiziellen XML-Quelle'}</strong> · Quellenabruf: ${date(source.retrieved)}<br>${esc(source.version.join(' · '))}<br><a href="${source.url}" target="_blank" rel="noopener noreferrer">Gesetze im Internet</a>${source.pdfUrl?` · <a href="${source.pdfUrl}" target="_blank" rel="noopener noreferrer">Original-PDF</a>`:''}${p.hasGraphics?'<br>Enthaltene Grafiken sind in der Original-PDF unverändert dargestellt.':''}</div><div class="reader-layout"><article class="law-reader ${large?'large':''}" id="law-reader">${p.sections.map(n=>n.kind==='heading'?`<h2 id="${n.id}">${esc(n.label)}</h2>`:`<section class="norm" id="${n.id}"><h3>${esc(n.label)}</h3><div class="law-text">${n.html}</div>${n.notes?`<div class="law-notes">${n.notes}</div>`:''}</section>`).join('')}</article><aside class="reader-side"><section class="contents-panel"><h2>Im Gesetz blättern</h2><select id="paragraph-picker" aria-label="Zum Paragraphen springen"><option value="">Paragraph auswählen …</option>${p.sections.filter(n=>n.kind==='norm').map(n=>`<option value="${n.id}">${esc(n.label)}</option>`).join('')}</select><h3>Quellenfassung</h3><p>Die Texte werden für die Bildschirmansicht übernommen. Den Fassungsstand entnehmen Sie der Quellenangabe oben.</p><a class="button" href="${source.pdfUrl||source.url}" target="_blank" rel="noopener noreferrer">Originalfassung ${icon('external')}</a><button class="button" data-view="collection">Alle Gesetze ${icon('book')}</button></section></aside></div>${end}`;}catch(error){if(token===readerToken&&$('#reader-content'))$('#reader-content').innerHTML=`<div class="reader-error"><strong>Text derzeit nicht verfügbar.</strong><p>${esc(error.message)}</p><a class="button" href="${l.url}" target="_blank" rel="noopener noreferrer">Offizielle Quelle öffnen ${icon('external')}</a></div>`;}}
function show(content,title='AUSHANG.'){if($('#dialog').open)$('#dialog').close();$('#dialog-eyebrow').textContent=title;$('#dialog-content').innerHTML=content;$('#dialog').showModal();}
const imprint=`<h2 id="dialog-title" class="dialog-title">Impressum</h2><section class="detail-section"><h3>Diensteanbieter nach § 5 DDG</h3><p><strong>DefiDev · Inhaber: Ümit Durmaz</strong><br>Proviantbachstr. 19B<br>86153 Augsburg<br>Deutschland</p><h3>Kontakt</h3><p><a href="mailto:Umit.durmaz@gmx.de">Umit.durmaz@gmx.de</a></p><p>Dieser Dienst richtet sich an Unternehmen. Anbieterangaben entsprechen dem bestehenden DefiDev-Impressum. Stand: 04.11.2026.</p><a href="https://www.gesetze-im-internet.de/ddg/__5.html" target="_blank" rel="noopener noreferrer">§ 5 DDG</a></section>`;
const privacy=`<h2 id="dialog-title" class="dialog-title">Datenschutzhinweise</h2><section class="detail-section"><h3>Verantwortlicher</h3><p>DefiDev · Ümit Durmaz, Proviantbachstr. 19B, 86153 Augsburg. Kontakt: <a href="mailto:Umit.durmaz@gmx.de">Umit.durmaz@gmx.de</a>.</p><h3>Verarbeitete Daten und Zwecke</h3><p>Gespeichert werden Benutzername, ein gesalzener Passwort-Hash, ein Hash des Wiederherstellungscodes, Firmenname, Werk, Geschäftsadresse, Nutzungsstatus, vereinbartes Gültigkeitsende oder unbefristete Freigabe, Freischalt-/Sperrvermerke mit Rechnungs-/Zahlungsreferenz, Favoriten und technische Sitzungsdaten. Die Angaben ermöglichen den Standortzugang, seine Absicherung und die standortbezogene Nutzung. Zusätzlich können berechtigte Nutzer betriebliche Bekanntmachungen wie Beschwerdestellenkontakte und Behördenanschriften hinterlegen. Entwürfe sind nur in der Passwortverwaltung sichtbar; veröffentlichte Fassungen stehen ausschließlich den freigeschalteten Zugängen desselben Werkes zur Verfügung. Verantwortlichkeit und Berechtigung für diese Inhalte liegen beim bereitstellenden Unternehmen. Das Passwort wird nicht im Klartext gespeichert. Eine E-Mail-Adresse und Namen einzelner Beschäftigter werden für den Portalzugang nicht verlangt. Im optionalen Dokumentenbereich werden nur vom Standortinhaber selbst hochgeladene Dateien sowie Titel, Art, Version, Dokumentdatum, Freigabestatus und Dateimetadaten verarbeitet. Entwürfe sind nur in der Passwortverwaltung sichtbar; veröffentlichte Dateien nur für autorisierte Nutzer desselben Standortzugangs. Es gibt keine öffentlichen Dateifreigaben. Der monatliche Abgleich amtlicher Rechtsquellen liest oder verändert diese Dateien nicht. Im optionalen BV-Linkbereich werden Titel, Linkadresse, Version und Veröffentlichungsstatus gespeichert. BV-Dateien werden dabei nicht auf dieses Portal kopiert. Entwürfe bleiben in der Passwortverwaltung, veröffentlichte Verknüpfungen im jeweiligen Werkzugang. Öffnen oder Teilen eines Links richtet sich nach den Berechtigungen des Zielsystems; der Portalzugang erteilt dort keine Berechtigungen.</p><h3>Rechtsgrundlagen</h3><p>Art. 6 Abs. 1 Buchst. b DSGVO, soweit die Verarbeitung zur Bereitstellung des vereinbarten Zugangs oder vorvertraglicher Maßnahmen erforderlich ist. Bei betrieblichen Nutzern und für die Absicherung des Dienstes Art. 6 Abs. 1 Buchst. f DSGVO; berechtigte Interessen sind die sichere, zuverlässige Bereitstellung und die Verhinderung von Missbrauch. Standortangaben sind für diesen standortgebundenen Dienst erforderlich; ohne sie wird kein Konto angelegt.</p><h3>Technische Bereitstellung</h3><p>Das Portal wird über OpenAI Sites mit Cloudflare-Diensten für Ausführung, Datenbank und Speicherung bereitgestellt. Die Anbieter verarbeiten technische Verbindungsdaten, insbesondere IP-Adresse und Abrufdaten. Es sind keine Analyse- oder Werbedienste eingebunden. Zugriffe auf verlinkte externe Quellen unterliegen deren Datenschutzbedingungen. Informationen der Anbieter: <a href="https://openai.com/policies/privacy-policy/" target="_blank" rel="noopener noreferrer">OpenAI</a> und <a href="https://www.cloudflare.com/privacypolicy/" target="_blank" rel="noopener noreferrer">Cloudflare</a>. Die Anbieter können Daten auch außerhalb der EU verarbeiten; die für den konkreten kommerziellen Betrieb erforderlichen Vertrags- und Transferregelungen sind vor dessen Aufnahme festzulegen.</p><h3>Speicherdauer und Browser</h3><p>Kontodaten und Favoriten bleiben für die Dauer des bereitgestellten Zugangs gespeichert; freiwillige Firmendokumente können in den Papierkorb verschoben, wiederhergestellt und gesondert endgültig gelöscht werden. Ausgeblendete Bereiche und Papierkorbeinträge bleiben bis zur Löschung gespeichert. Das hochladende Unternehmen bestimmt Zweck und Berechtigung seiner Dokumentinhalte; soweit hierfür eine Auftragsverarbeitung vorliegt, sind die konkreten Bedingungen gesondert zu vereinbaren.  Lösch- und Berichtigungswünsche können an den Verantwortlichen gerichtet werden. Eine technisch erforderliche Sitzung wird mit einem HttpOnly-Cookie geführt: regulär bis zu 12 Stunden. Ein ausdrücklich eingerichteter Gerätezugang speichert zusätzlich einen nicht exportierbaren kryptografischen Schlüssel als CryptoKey in der IndexedDB dieses Browserprofils. Der Server speichert nur den öffentlichen Schlüssel, Gerätename, Erstellungs-/Nutzungszeitpunkt und einen möglichen Widerruf. Bei jedem erneuten Öffnen weist der Browser den Besitz des Schlüssels mit einer einmaligen, zwei Minuten gültigen Challenge nach; dadurch kann er ohne Passwort eine neue Sitzung erhalten. Die Gerätefreigabe bleibt bis zum Widerruf bestehen; Löschen der Website-Daten, Browserwechsel, Passwortänderung oder Wiederherstellung erfordern eine neue Einrichtung. Der Link enthält keine Zugangsdaten. Abmelden beendet die aktuelle Sitzung, widerruft aber nicht die gesonderte Gerätefreigabe. Diese kann nach Passwortanmeldung unter „Mein Zugang“ widerrufen werden. Die lokale Speicherung dient dem ausdrücklich gewünschten Gerätezugang (§ 25 Abs. 2 Nr. 2 TDDDG). Sicherheitszähler enthalten nur pseudonymisierte Prüfschlüssel, keine im Anwendungssystem gespeicherten vollständigen IP-Adressen. Abgelaufene Zähler und Sitzungen werden beim monatlichen Wartungslauf entfernt. Technische Hosting-Protokolle richten sich zusätzlich nach den Bedingungen der Anbieter.</p><h3>Ihre Rechte</h3><p>Nach Maßgabe der DSGVO bestehen Rechte auf Auskunft, Berichtigung, Löschung, Einschränkung, Datenübertragbarkeit und Widerspruch bei einer Verarbeitung nach Art. 6 Abs. 1 Buchst. f DSGVO. Zudem können Sie sich bei einer Datenschutzaufsichtsbehörde beschweren, insbesondere beim <a href="https://www.lda.bayern.de/" target="_blank" rel="noopener noreferrer">Bayerischen Landesamt für Datenschutzaufsicht</a>. Es erfolgt keine automatisierte Entscheidung über Personen im Sinne von Art. 22 DSGVO.</p><p>Stand: 06.11.2026 · <a href="https://eur-lex.europa.eu/eli/reg/2016/679/oj?locale=de" target="_blank" rel="noopener noreferrer">DSGVO, insbesondere Art. 5, 6 und 13</a>.</p></section>`;
const terms=`<h2 id="dialog-title" class="dialog-title">Nutzungsumfang</h2><section class="detail-section"><h3>Ein Zugang – ein benannter Standort</h3><p>Der Zugang ist dem bei der Registrierung angegebenen Unternehmen, Werk und der vollständigen Geschäftsadresse zugeordnet. Die Nutzung ist für diesen Standort bestimmt. Für zusätzliche Werke oder Adressen ist ein eigener Standortzugang bzw. eine gesonderte Vereinbarung erforderlich.</p><h3>Geschäftlicher Standortzugang</h3><p>Der Dienst richtet sich an Unternehmen und berechtigte betriebliche Nutzer. Die Registrierung ist eine unverbindliche Zugangsanfrage; sie schaltet noch keine Gesetzessammlung frei und löst keine automatische Zahlung oder ein Abonnement aus. Preis, Zahlungsweg, Leistungsumfang und Laufzeit werden mit dem Anbieter gesondert vereinbart. Erst nach bestätigtem Zahlungseingang und Freigabe durch den Anbieter ist die Nutzung innerhalb der vereinbarten Laufzeit möglich. Die Laufzeit wird nicht automatisch verlängert.</p><h3>Gesetzessammlung und Bekanntmachung</h3><p>Die Sammlung umfasst gesetzliche Texte, gekennzeichnete Auszüge und Unfallverhütungsvorschriften aus offiziellen Quellen. Nicht jeder enthaltene Text begründet eine eigenständige Aushangpflicht in jedem Unternehmen. Der Arbeitgeber bleibt für die konkrete Auswahl, den tatsächlichen Zugang aller betroffenen Beschäftigten und gesonderte betriebliche Bekanntmachungen verantwortlich. Dazu gehören gegebenenfalls Tarifverträge, Betriebsvereinbarungen und Angaben zu Beschwerdestellen oder Aufsichtsbehörden. Der optionale Bereich „Firmendokumente“ kann hierfür vom Standortinhaber aktiviert werden. Die Auswahl, Veröffentlichung und vorgeschriebene Bekanntmachungsform bleiben vom Unternehmen zu prüfen.</p><h3>Textfassungen und Aktualisierung</h3><p>Ein monatlicher Abgleich der hinterlegten Quellen ist vorgesehen. Erst nach erfolgreicher vollständiger Verarbeitung wird der neue Prüfzeitpunkt aktiviert. Bei Fehlern bleibt der letzte vollständige Stand verfügbar. Die jeweilige Quellenfassung und der Abrufzeitpunkt sind beim einzelnen Text angegeben. Erforderliche Aushänge vor Ort, etwa Flucht- und Rettungspläne, sind gesondert bereitzustellen.</p><h3>Gesetzestexte</h3><p>Die Nutzungszuordnung betrifft den Portalzugang. Sie begründet kein ausschließliches Recht an frei zugänglichen Gesetzestexten. Für Gesetze und Verordnungen ist insbesondere <a href="https://www.gesetze-im-internet.de/urhg/__5.html" target="_blank" rel="noopener noreferrer">§ 5 UrhG</a> zu beachten.</p></section>`;
function legalPage(which){if(which==='privacy')return show(privacy);if(which==='imprint')return show(imprint);if(which==='terms')return show(terms);show(`<h2 id="dialog-title" class="dialog-title">Aktualisierung der Sammlung</h2><section class="detail-section"><h3>Letzte vollständige Aktualisierung</h3><p>${meta?date(meta.lastSuccessfulCheck):'Der Prüfzeitpunkt wird geladen.'}</p><h3>Monatlicher Quellenabgleich</h3><p>Jeweils am 1. eines Monats um 06:00 Uhr (Europe/Berlin) prüft ein mit diesem Portal verknüpfter ChatGPT-Auftrag die 44 freigegebenen amtlichen Quellen und übernimmt die geprüften Quelldateien. Kundenkonten, Werkadressen, Gerätefreigaben und Favoriten bleiben unverändert. Ein neuer Stand wird als zusammengehörige Fassung aktiviert, sobald alle Quellen erfolgreich verarbeitet wurden. Fehler verändern den letzten erfolgreichen Prüfzeitpunkt nicht.</p><h3>Welche Daten ändern sich?</h3><p>Aktualisiert werden ausschließlich die öffentlichen Rechtsquellen. Konten, Standortadressen und Favoriten werden vom Quellenabgleich nicht verändert.</p><p>Die Quellenfassung eines einzelnen Gesetzes kann älter sein als der letzte Prüftermin, wenn sich der Gesetzestext seitdem nicht geändert hat.</p></section>`);}
async function install(){
 if(device.activeId&&installPrompt){try{await installPrompt.prompt();await installPrompt.userChoice;}catch{}installPrompt=null;return;}
 const localId=device.activeId||deviceList.find(d=>d.local)?.id;
 show(`<h2 id="dialog-title" class="dialog-title">Ihr Firmenzugang auf dem Desktop.</h2><section class="detail-section">${localId?`<p>Die Verknüpfung öffnet den freigeschalteten Geräte-Link mit Ihrem Werk und Ihrer Adresse.</p><div class="device-actions"><button class="button primary" data-action="device-download" data-id="${localId}">Windows-Verknüpfung herunterladen</button><button class="button" data-action="device-copy" data-id="${localId}">Link kopieren</button>${!device.activeId?`<button class="button" data-action="device-open" data-id="${localId}">Geräte-Link öffnen</button>`:''}</div><p>Die Datei aus „Downloads“ auf den Desktop verschieben. Mit demselben Browserprofil öffnen; der Standardbrowser kann in Windows geändert werden.</p>`:`<p>Richten Sie zuerst diesen Browser als Firmengerät ein. Danach erhalten Sie einen eigenen Geräte-Link und eine Windows-Verknüpfung.</p><button class="button primary" data-action="device-setup">Firmencomputer einrichten</button>`}<h3>Alternativ als App installieren</h3><p>Öffnen Sie zuerst Ihren Geräte-Link. In <strong>Edge</strong>: Browsermenü → Weitere Tools → Apps → Diese Website als App installieren. Anschließend unter <code>edge://apps</code> → Details → Desktop-Verknüpfung erstellen.</p><p>In Chrome den Installations-Menüpunkt verwenden. Auf iPhone/Safari: „Teilen“ → „Zum Home-Bildschirm“; je nach Browser kann danach eine eigene Gerätefreigabe erforderlich sein.</p><p class="legal-note">Eine Website darf sich nicht ohne Ihre Browserbestätigung auf dem Desktop installieren. Die Gerätefreigabe bleibt bei Verbindungsunterbrechungen erhalten. Gelöschte Browserdaten oder ein Browserwechsel erfordern eine neue Freigabe.</p></section>`);
}
function error(message){const e=$('#form-error');if(e)e.textContent=message;else toast(message);}
function downloadCode(){const a=document.createElement('a');const content=`aushang. – Wiederherstellungscode\nBenutzername: ${account?.username||''}\nStandort: ${account?.work||''}\n\n${recoveryCode}\n\nSicher aufbewahren. Dieser Code ermöglicht das Zurücksetzen des Passworts.\n`;a.href=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));a.download='aushang-wiederherstellungscode.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a[data-scroll]');if(!b)return;if(b.dataset.auth){signupDraft=null;authView=b.dataset.auth;render();}else if(b.dataset.view)navigate(b.dataset.view);else if(b.dataset.law)openLaw(b.dataset.law);else if(b.dataset.favorite)setFavorite(b.dataset.favorite);else if(b.dataset.scroll){e.preventDefault();document.getElementById(b.dataset.scroll)?.scrollIntoView({behavior:'smooth',block:'start'});}else if(b.dataset.page)legalPage(b.dataset.page);else if(b.dataset.action){const action=b.dataset.action;if(action==='signup-back'){signupDraft=null;render();}if(action==='install')install();if(action==='device-enroll')enrollHere(b);if(action==='device-open')location.href=device.url(b.dataset.id||createdDevice.id);if(action==='device-setup'){$('#dialog').close();navigate('account');}if(action==='device-copy')copyDeviceLink(b.dataset.id||createdDevice.id);if(action==='device-download')device.download(b.dataset.id||createdDevice.id);if(action==='device-revoke')revokeHere(b.dataset.id,b);if(action==='device-retry')openDevice();if(action==='check-access'){try{await hydrateAccount();toast(access?.canRead?'Ihr Standortzugang ist freigeschaltet.':'Die Freischaltung steht noch aus.');}catch(err){toast(err.message);}}if(action==='font'){large=!large;$('#law-reader')?.classList.toggle('large',large);}if(action==='print')window.print();if(action==='copy-code'){try{await navigator.clipboard.writeText(recoveryCode);toast('Wiederherstellungscode kopiert.');}catch{toast('Bitte den Code markieren und kopieren.');}}if(action==='download-code')downloadCode();if(action==='finish-recovery'){if(!$('#code-saved')?.checked)return toast('Bitte bestätigen, dass Sie den Code gesichert haben.');recoveryCode='';navigate('account');if(access?.canRead)await enrollHere(b);}if(action==='logout'){try{await api('/api/auth/logout','POST',{});account=null;access=null;clearPortalState();view='aushang';signupDraft=null;recoveryCode='';authView='login';history.replaceState(null,'','#anmelden');if(device.activeId){deviceError={message:'Der Gerätezugang ist geschlossen. Mit „Sammlung öffnen“ können Sie ihn auf diesem Browser wieder öffnen.'};}render();toast('Sie wurden abgemeldet.');}catch(err){toast(err.message);}}}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['login-form','register-account-form','register-site-form','recover-form','password-form'].includes(form.id))return;e.preventDefault();const loginIntent=e.submitter?.value||'portal';const b=Object.fromEntries(new FormData(form));if($('#form-error'))$('#form-error').textContent='';const button=form.querySelector('button[type=submit]');button.disabled=true;
 try{
  if(form.id==='register-account-form'){if(b.password!==b.confirmPassword)throw Error('Die Passwörter stimmen nicht überein.');signupDraft={username:b.username,password:b.password};render();return;}
  if(form.id==='register-site-form'){if(!signupDraft)throw Error('Bitte zuerst die Zugangsdaten festlegen.');const r=await api('/api/auth/register','POST',{...signupDraft,...b,acceptSiteScope:b.acceptSiteScope==='on',businessOnly:b.businessOnly==='on'});signupDraft=null;recoveryCode=r.recoveryCode;await hydrateAccount();return;}
  if(form.id==='login-form'){await api('/api/auth/login','POST',{...b,remember:false});view='aushang';history.replaceState(null,'','#aushang');await hydrateAccount();if((b.setupDevice==='on'||loginIntent==='device')&&access?.canRead){const local=deviceList.find(d=>d.local);if(local)location.href=device.url(local.id);else await enrollHere(button,true);}return;}
  if(form.id==='recover-form'){if(b.newPassword!==b.confirmPassword)throw Error('Die Passwörter stimmen nicht überein.');const r=await api('/api/auth/recover','POST',b);recoveryCode=r.recoveryCode;await hydrateAccount();return;}
  if(form.id==='password-form'){if(b.newPassword!==b.confirmPassword)throw Error('Die Passwörter stimmen nicht überein.');await api('/api/auth/password','POST',b);await hydrateAccount();toast('Passwort geändert. Frühere Sitzungen wurden beendet.');}
 }catch(err){error(err.message);}finally{if(button.isConnected)button.disabled=false;}
});
document.addEventListener('change',e=>{if(e.target.id==='paragraph-picker'&&e.target.value)document.getElementById(e.target.value)?.scrollIntoView({behavior:'smooth',block:'start'});});
$('#dialog-close').addEventListener('click',()=>$('#dialog').close());$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
window.addEventListener('focus',async()=>{try{const latest=await api('/api/public/meta');meta=latest;updateDate();}catch{}});
function devicePanel(){
 const id=access?.deviceId;
 if(access?.kind==='device')return `<section class="form-panel device-panel"><span class="eyebrow">DIESER BROWSER IST FREIGESCHALTET</span><h2>Ihr persönlicher Geräte-Link.</h2><p>Dieser Link öffnet Ihr registriertes Werk automatisch auf diesem Browser. Kopieren allein schaltet keinen anderen Computer frei.</p><div class="device-actions"><button class="button primary" data-action="device-download" data-id="${id}">Windows-Verknüpfung herunterladen</button><button class="button" data-action="device-copy" data-id="${id}">Link kopieren</button><button class="button" data-action="install">Als App installieren</button></div><p class="legal-note">Internetunterbrechungen und das Schließen des Browsers entfernen die Freigabe nicht. Nach Löschen der Browserdaten, Browserwechsel oder Widerruf muss das Gerät neu eingerichtet werden.</p></section>`;
 return `<section class="form-panel device-panel"><span class="eyebrow">EINMAL EINRICHTEN · DIREKT ÖFFNEN</span><h2>Dieser Firmencomputer.</h2><p>Erstellen Sie einen Geräte-Link für diesen Browser. Danach öffnet er die Sammlung ohne erneute Eingabe von Benutzername und Passwort – auch nach einem Neustart oder einer Internetunterbrechung.</p><label class="field">Name dieses Geräts<input id="device-name" value="Firmencomputer" maxlength="80" autocomplete="off"></label><button class="button primary" data-action="device-enroll">Geräte-Link für diesen Browser erstellen ${icon('arrow')}</button><p class="legal-note">Gilt für dieses Browserprofil. Ein anderer Computer benötigt eine eigene Freigabe nach Anmeldung. Bitte keinen privaten Modus verwenden und die Website-Daten nicht automatisch beim Schließen löschen.</p>${deviceList.length?`<h3 class="device-list-title">Freigeschaltete Browser</h3><div class="device-list">${deviceList.map(d=>`<div class="device-row"><div><strong>${esc(d.label)}</strong><small>${d.local?'Dieser Browser · ':''}Eingerichtet: ${date(d.createdAt*1000)}</small></div><div class="device-actions">${d.local?`<button class="button" data-action="device-open" data-id="${d.id}">Öffnen</button><button class="button" data-action="device-download" data-id="${d.id}">Verknüpfung</button>`:''}<button class="text-button" data-action="device-revoke" data-id="${d.id}">Widerrufen</button></div></div>`).join('')}</div>`:''}</section>`;
}
function deviceGate(){return `<header class="public-header">${brand()}<span class="scope-label">Geschützter Firmencomputer</span></header><main id="main" class="device-gate"><section class="auth-card"><span class="eyebrow">IHR GERÄTE-LINK</span><h1>${deviceBusy?'Firmenzugang wird geöffnet.':'Ihr Firmenzugang.'}</h1><p>${esc(deviceError?.message||'Der lokale Geräteschlüssel wird geprüft. Benutzername und Passwort werden auf dieser Seite nicht abgefragt.')}</p>${!deviceBusy?`<div class="device-actions"><button class="button primary" data-action="device-retry">Sammlung öffnen ${icon('arrow')}</button><a class="button" href="/#anmelden">Anderen Browser freischalten</a></div>`:''}<p class="legal-note">Die Berechtigung liegt in diesem Browser, nicht im Link. Die Verwaltungsanmeldung ist getrennt erreichbar.</p></section></main>`;}
async function loadDevices(){deviceList=(await api('/api/devices')).devices;for(const d of deviceList)d.local=await device.hasKey(d.id).catch(()=>false);}
async function enrollHere(button,openAfter=false){
 button.disabled=true;try{createdDevice=await device.enroll($('#device-name')?.value||'Firmencomputer');await loadDevices();if(openAfter){location.href=device.url(createdDevice.id);return;}render();show(`<h2 id="dialog-title" class="dialog-title">Dieser Browser ist freigeschaltet.</h2><section class="detail-section"><p>Der Geräte-Link gehört zu <strong>${esc(account.company)} · ${esc(account.work)}</strong>. Er öffnet sich nur mit dem hier gespeicherten Geräteschlüssel.</p><label class="field">Ihr Geräte-Link<input readonly value="${esc(createdDevice.url)}" aria-label="Ihr Geräte-Link"></label><div class="device-actions"><button class="button primary" data-action="device-download" data-id="${createdDevice.id}">Windows-Verknüpfung herunterladen</button><button class="button" data-action="device-copy" data-id="${createdDevice.id}">Link kopieren</button><button class="button" data-action="device-open" data-id="${createdDevice.id}">Geräte-Link öffnen ${icon('arrow')}</button></div><p>Die heruntergeladene Datei auf den Desktop verschieben. Sie enthält den Link, keine Zugangsdaten. Öffnen Sie sie mit demselben Browserprofil.</p></section>`);}catch(e){toast(e.message);}finally{if(button.isConnected)button.disabled=false;}
}
async function revokeHere(id,button){button.disabled=true;try{await api('/api/devices/'+id,'DELETE');await loadDevices();render();toast('Gerätefreigabe widerrufen. Der alte Link öffnet die Sammlung nicht mehr.');}catch(e){toast(e.message);button.disabled=false;}}
async function copyDeviceLink(id){try{await navigator.clipboard.writeText(device.url(id));toast('Geräte-Link kopiert.');}catch{show(`<h2 id="dialog-title" class="dialog-title">Geräte-Link kopieren</h2><label class="field">Link<input readonly value="${esc(device.url(id))}"></label>`);}}
async function openDevice(){
 if(deviceBusy)return;deviceBusy=true;deviceError=null;render();try{await device.unlock();await hydrateAccount();}catch(e){account=null;access=null;clearPortalState();deviceError=e;}finally{deviceBusy=false;render();}
}
window.addEventListener('online',()=>{if(device.activeId)openDevice();});
function pendingShell(){return publicHeader()+`<main class="account-page pending-page" id="main">${scope()}<section class="form-panel"><span class="eyebrow">GESCHÄFTLICHER STANDORTZUGANG</span><h1 class="page-title">${account.licenseValidUntil?'Laufzeit beendet.':'Ihre Zugangsanfrage ist gespeichert.'}</h1><p>Benutzername: <strong>${esc(account.username)}</strong></p><p>Die Gesetzessammlung und Geräte-Links sind erst nach Freischaltung für die vereinbarte Laufzeit verfügbar.</p><ol class="activation-steps"><li><strong>Angebot vereinbaren.</strong> Preis, Zahlungsweg und Laufzeit stimmen Sie mit dem Anbieter ab.</li><li><strong>Zahlung bestätigen lassen.</strong> Nach Zahlungseingang schaltet der Anbieter Ihren registrierten Standort bis zum vereinbarten Datum frei.</li><li><strong>Firmencomputer einrichten.</strong> Danach erhalten Sie Ihren Geräte-Link ohne wiederkehrende Passworteingabe.</li></ol><p>Es wurde keine Zahlung eingezogen und kein automatisches Abonnement angelegt.</p><div class="device-actions"><a class="button primary" href="mailto:Umit.durmaz@gmx.de">Angebot / Freischaltung anfragen</a><button class="button" data-action="check-access">Freischaltung prüfen</button><button class="button" data-view="documents">Eigene Dokumente verwalten</button><button class="text-button" data-action="logout">Abmelden</button></div></section></main>`;}
async function synchronizeAccess(){
 if(!account||document.hidden||recoveryCode)return;
 try{const r=await api('/api/me');if(!r.account){if(device.activeId)await openDevice();else{account=null;access=null;clearPortalState();view='aushang';render();}return;}
 const changed=account.id!==r.account.id||!!access?.canRead!==!!r.access?.canRead;if(changed){view='aushang';await hydrateAccount();}else{account=r.account;access=r.access;meta=r.meta;favorites=r.favorites||[];updateDate();refreshNotices();}
 }catch{}
}
setInterval(synchronizeAccess,5*60*1000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)synchronizeAccess();});
const topicLabels={umwelt:'Umwelt',arbeitssicherheit:'Arbeitssicherheit',brandschutz:'Brandschutz',gefahrstoffe:'Gefahrstoffe','emas-iso14001':'EMAS / ISO 14001'};
const orderTitle=new Intl.Collator('de',{sensitivity:'base',numeric:true});
const sortTitle=(a,b)=>orderTitle.compare(a.title,b.title);
const fold=v=>String(v||'').toLocaleLowerCase('de').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ß/g,'ss');
const legalEntries=()=>catalog.filter(x=>x.legalIndex);
const activeTopic=()=>topics.find(t=>t.id===view);
function navItems(){return [['aushang','Aushangpflichtige Gesetze'],['collection','Alle Gesetze'],...Object.entries(topicLabels),['site','Bekanntmachungen'],['bv','Betriebsvereinbarungen'],['documents','Firmendokumente']];}
function publicHeader(){const open=account&&access?.canRead;return `<header class="portal-header ${open?'':'entry-header'}"><div class="masthead"><a class="brand" href="#home"><span class="brand-sign" aria-hidden="true">§</span><span>aushang<span class="brand-dot">.</span><small>RECHT & BETRIEB</small></span></a><div class="masthead-tools">${open?'<a href="/quellen">Quellenverzeichnis</a>':''}<button data-page="imprint">Impressum</button><button data-page="privacy">Datenschutz</button>${open?`${access?.kind==='password'?`<button class="account-link" data-view="account">${icon('user')}${esc(account.username)}</button>`:'<span class="reader-access-label">Gemeinsamer Lesezugang</span>'}`:''}</div></div>${open?`<nav class="topic-nav" aria-label="Hauptnavigation">${navItems().map(([id,label])=>`<button data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${esc(label)}</button>`).join('')}</nav>`:''}</header>`;}
function scope(){return `<section class="site-scope" aria-label="Verbindlicher Nutzungsstandort"><div>${icon('pin')}<strong>${esc(account.company)} · ${esc(account.work)}</strong><span>${esc(account.street)} ${esc(account.houseNumber)}, ${esc(account.postalCode)} ${esc(account.city)}</span></div><small>Gehört ausschließlich zu diesem Werk und dieser Adresse</small></section>`;}
function leftRail(){
 const topic=activeTopic(),list=topic?topic.items.map(x=>catalog.find(y=>y.id===x.recordId)).filter(Boolean):legalEntries();
 const categories=topic?[...new Set(list.map(x=>x.type))]:[...new Set(legalEntries().map(x=>x.group))];
 return `<aside class="left-rail"><div class="rail-heading">BIBLIOTHEK</div><nav class="rail-nav"><button data-view="aushang" class="${view==='aushang'?'current':''}">${icon('pin')}Aushang & Bekanntgabe</button><button data-view="collection" class="${view==='collection'?'current':''}">${icon('book')}Alle Gesetze <span>${legalEntries().length}</span></button><button data-view="favorites" class="${view==='favorites'?'current':''}">${icon('bookmark')}Favoriten <span>${favorites.length}</span></button></nav>${!['account','documents','reader'].includes(view)?`<div class="rail-heading">${topic?'QUELLENART':'RECHTSGEBIETE'}</div><nav class="rail-filters" aria-label="Liste filtern"><button data-filter="" class="${!category?'selected':''}">Alle anzeigen</button>${categories.map(g=>`<button data-filter="${esc(g)}" class="${category===g?'selected':''}">${esc(g)}</button>`).join('')}</nav>`:''}<div class="rail-heading">DIREKTZUGRIFF</div><nav class="rail-nav"><button data-law="arbzg">Arbeitszeitgesetz</button><button data-law="agg">Gleichbehandlungsgesetz</button><button data-law="muschg">Mutterschutzgesetz</button><button data-view="bv">Betriebsvereinbarungen</button></nav><div class="rail-foot">Gesetze, Verordnungen und betriebliche Dokumente an einem Ort.</div></aside>`;
}
function rightRail(){return `<aside class="right-rail"><section class="sidebar-module werk-module"><div class="module-heading">BEKANNTMACHUNGEN IM WERK</div><div id="werk-notices">${noticeList()}</div><button class="side-link" data-view="site">Alle Werkangaben ansehen ${icon('arrow')}</button>${access?.kind==='password'?'<button class="text-button manage-notices" data-view="site-admin">Werkangaben verwalten</button>':''}</section><section class="sidebar-module edition-module"><div class="module-heading">QUELLENSTAND</div><div class="date-display">${meta?date(meta.lastSuccessfulCheck):'–'}</div><p>Letzter vollständiger Abgleich der ${meta?.total||44} hinterlegten Quellen.</p><button class="text-button" data-page="updates">Aktualisierung im Detail ${icon('arrow')}</button><p class="mini-note">Zusätzliche Quellenlinks: geprüft am ${date(portalInfo?.checkedAt||'2026-11-06')}.</p></section><section class="sidebar-module"><div class="module-heading">DIESES LESEGERÄT</div><p class="kiosk-status">${access?.kind==='device'?'Freigeschalteter Firmencomputer':'Verwaltungszugang mit Passwort'}</p><button class="side-link" data-kiosk-action="fullscreen">Vollbild ${icon('external')}</button><button class="side-link" data-view="favorites">Favoriten dieses Werks <span>${favorites.length}</span></button><button class="side-link" data-kiosk-action="access-help">Hinweise zur Nutzung ${icon('arrow')}</button>${access?.kind==='password'?'<button class="side-link" data-view="account">Zugang & Desktop-Link verwalten '+icon('arrow')+'</button>':''}</section><section class="sidebar-module"><a class="side-link" href="/quellen">Quellenverzeichnis ${icon('external')}</a><button class="side-link" data-page="privacy">Datenschutz ${icon('arrow')}</button></section></aside>`;}
function portalShell(){const directory=['aushang','collection','favorites','search',...Object.keys(topicLabels)].includes(view);return `${publicHeader()}<main id="main" class="portal-main">${scope()}<div class="workspace">${leftRail()}<div class="workspace-content">${directory?'':portalSearch()}${view==='account'?accountPage():view==='bv'?bvPage():view==='site-admin'?siteEditor():view==='site'?sitePage():view==='documents'?documentsPage():view==='reader'?readerShell():directoryPage()}</div>${rightRail()}</div></main>`;}
function portalSearch(){return `<form id="global-library-search" role="search" class="search-toolbar global-search"><label class="search-field">${icon('file')}<input id="global-law-search" type="search" aria-label="Alle Gesetze und Regeln durchsuchen" placeholder="Gesetze und Regeln in allen Bereichen suchen" autocomplete="off"></label><button class="button primary" type="submit">Suchen</button></form>`;}
function clearPortalState(){bvData=null;bvLoading=false;bvTrash=false;bvToken++;noticeState=null;noticeLoading=false;noticeDirty=false;noticeToken++;catalog=[];topics=[];portalInfo=null;favorites=[];docState=null;docTrash=false;docLoading=false;documentRequestToken++;deviceList=[];query='';category='';letter='';readerId='';readerToken++;}
function accountShell(){return portalShell();}
function authPage(){const login=authView==='login';return `${publicHeader()}<main id="main" class="registration-layout entry-layout"><aside><span class="eyebrow">GESCHÜTZTER STANDORTZUGANG</span><h1>${login?'Ihr Portal. Ihr Standort.':authView==='recover'?'Zugang wiederherstellen':'Ein Zugang für Ihren Standort'}</h1><p>${login?'Melden Sie sich mit Ihrem Firmenzugang an. Ihr Portal ist dem registrierten Werk und seiner Adresse zugeordnet.':authView==='recover'?'Verwenden Sie den bei der Registrierung gesicherten Wiederherstellungscode.':'Firmenname, Werk und Adresse werden dem Zugang verbindlich zugeordnet. Die Freischaltung erfolgt nach gesonderter Vereinbarung.'}</p>${login?'<div class="entry-rule"></div><p class="entry-caption">Bereits eingerichtete Firmencomputer öffnen ihren persönlichen Geräte-Link direkt.</p>':'<button class="text-button" data-auth="login">Zurück zur Anmeldung</button>'}</aside><section class="auth-card" id="access-panel">${authFields()}${login?'<p class="create-access">Noch kein Zugang? <button class="text-button" data-auth="register">Zugang anfragen</button></p>':''}</section></main>`;}
function directoryItems(){
 const topic=activeTopic();let rows;
 if(topic)rows=topic.items.map(x=>({...catalog.find(e=>e.id===x.recordId),...x,id:x.recordId,short:x.abbreviation||catalog.find(e=>e.id===x.recordId)?.short,description:x.description}));
 else if(view==='favorites')rows=catalog.filter(x=>favorites.includes(x.id));
 else if(view==='search')rows=catalog;
 else rows=legalEntries().filter(x=>view!=='aushang'||x.noticeRules?.length);
 return rows.filter(x=>!category||(topic?x.type:x.group)===category).filter(x=>!query||fold([x.title,x.short,x.description,x.group,x.type].join(' ')).includes(fold(query))).filter(x=>!letter||fold(x.title).charAt(0).toUpperCase()===letter).sort(sortTitle);
}
function directoryHeading(){if(view==='search')return ['Suche in allen Bereichen','Gesetze, Verordnungen, technische Regeln und offizielle Quellen Ihres Standortportals.'];const topic=activeTopic();if(topic)return [topic.title,topic.intro];if(view==='aushang')return ['Aushangpflichtige Gesetze','Gesetze, Verordnungen und Regeln zur Einsicht. Die jeweilige Bekanntmachungspflicht steht direkt beim Titel.'];if(view==='favorites')return ['Ihre Favoriten','Gemerkte Gesetze, Regeln und offizielle Quellen für Ihren Standortzugang.'];return ['Alle Gesetze','Gesetze und Verordnungen von A bis Z. Hinterlegte Fassungen und ergänzende amtliche Quellen direkt im Verzeichnis.'];}
function directoryPage(){const [title,description]=directoryHeading(),topic=activeTopic();return `<div class="page-heading"><div><div class="breadcrumb">${view==='aushang'?'GESETZE & BETRIEBLICHE BEKANNTMACHUNGEN':'BIBLIOTHEK / '+esc(title)}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div></div><form id="library-search" role="search" class="search-toolbar"><label class="search-field"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><input id="law-search" type="search" value="${esc(query)}" placeholder="Titel, Abkürzung oder Stichwort suchen" aria-label="Gesetze und Quellen durchsuchen" autocomplete="off"></label><button class="button primary" type="submit">Suchen</button></form><div class="directory-toolbar"><span id="result-count" aria-live="polite"></span><span>Alphabetisch A–Z</span></div><nav class="alphabet" aria-label="Alphabetischer Schnellfilter"><button data-alpha="" class="${!letter?'selected':''}">Alle</button>${'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('').map(l=>`<button data-alpha="${l}" class="${letter===l?'selected':''}">${l}</button>`).join('')}</nav>${view==='aushang'?homeShortcuts():''}${topic&&topic.id==='emas-iso14001'?'<div class="context-note"><strong>ISO 14001:2026</strong> ist die aktuelle Ausgabe. Der Normvolltext wird beim offiziellen Anbieter lizenziert. Eine EMAS-Registrierung wird hier nicht automatisch mit Konformität zur neuen ISO-Ausgabe gleichgesetzt.</div>':''}<div class="table-heading"><span>KURZBEZEICHNUNG</span><span>TITEL / RECHTSQUELLE</span><span>ZUGRIFF</span><span></span></div><div id="law-results" class="law-results">${directoryRows()}</div>${view==='aushang'?'<p class="home-legal-note">Die hinterlegten Gesetzestexte ergänzen die betrieblichen Bekanntmachungen. Ihre tatsächliche Anwendbarkeit und die vorgeschriebene Form bleiben maßgeblich.</p>':''}<p class="directory-footnote">${topic?'Redaktionelle Auswahl offizieller Quellen. Technische Regeln, Normen und Arbeitshilfen sind als solche gekennzeichnet.':'Zusätzliche Titel öffnen beim amtlichen Herausgeber. „Im Portal“ kennzeichnet die hinterlegte Textfassung bzw. das Original-PDF.'}</p>`;}
function directoryRows(){const rows=directoryItems();return rows.length?rows.map(x=>lawRow(x)).join(''):`<div class="empty"><h2>${view==='favorites'&&!query?'Noch keine Favoriten':'Keine passenden Einträge'}</h2><p>${view==='favorites'&&!query?'Mit dem Lesezeichen neben einem Titel merken Sie sich die Quelle.':'Versuchen Sie eine andere Abkürzung oder setzen Sie die Filter zurück.'}</p><button class="button" data-action="clear-search">Filter zurücksetzen</button></div>`;}
function lawRow(l){const notices=view==='aushang'?l.noticeRules||[]:[],label=l.hosted?'Im Portal':'Originalquelle';return `<article class="law-row" data-entry="${esc(l.id)}"><div class="law-abbr">${esc(l.short)}</div><div class="law-information">${l.hosted?`<button class="law-title" data-law="${esc(l.id)}">${esc(l.title)}</button>`:`<a class="law-title" href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${esc(l.title)}</a>`}<div class="law-subline"><span>${esc(l.type)}</span>${l.select?'<span>Auszug</span>':''}${l.localPdf?'<span>BGN-Fassung</span>':''}${activeTopic()?`<span>${esc(l.provider||'Amtliche Quelle')}</span>`:`<span>${esc(l.group||'Weitere Rechtsgrundlagen')}</span>`}</div>${activeTopic()&&l.description?`<p class="source-description">${esc(l.description)}</p>`:''}${notices.length?`<details class="notice-details"><summary>${esc(notices.map(r=>r.basis).join(' · '))}</summary>${notices.map(r=>`<div><strong>${esc(r.trigger||'Anwendungsbereich der Vorschrift prüfen.')}</strong><p>${esc(r.requiredContent||'')}</p>${r.note?`<p>${esc(r.note)}</p>`:''}<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Rechtsgrundlage</a></div>`).join('')}</details>`:''}</div><div class="law-access">${l.hosted?`<button data-law="${esc(l.id)}">${label} ${icon('arrow')}</button><a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">Original ${icon('external')}</a>`:`<a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${label} ${icon('external')}</a>`}</div><button class="bookmark-button ${favorites.includes(l.id)?'saved':''}" data-favorite="${esc(l.id)}" aria-label="${esc(l.title)} ${favorites.includes(l.id)?'aus Favoriten entfernen':'merken'}" aria-pressed="${favorites.includes(l.id)}">${icon('bookmark')}</button></article>`;}
function refreshDirectory(){const target=$('#law-results');if(!target)return;target.innerHTML=directoryRows();const count=$('#result-count');if(count)count.textContent=`${directoryItems().length} Einträge${query?' · Suche: '+query:''}`;document.querySelectorAll('[data-alpha]').forEach(b=>b.classList.toggle('selected',b.dataset.alpha===letter));}
function noticeAppendix(){return `<section class="notice-appendix"><h2>Zusätzliche betriebliche Bekanntmachungen</h2><p>Je nach Betrieb sind etwa geltende Tarifverträge, Betriebsvereinbarungen, Arbeitszeit- und Pausenangaben für Jugendliche sowie zuständige Beschwerde- oder Aufsichtsstellen bekanntzumachen. Ein allgemeiner Gesetzestext enthält diese individuellen Angaben nicht.</p><button class="button" data-view="documents">Zu den optionalen Firmendokumenten ${icon('arrow')}</button></section>`;}
function render(){const open=!!(account&&access?.canRead);updateDate();$('#update-bar').hidden=!open;document.querySelectorAll('[data-portal-only]').forEach(e=>e.hidden=!open);$('#app').innerHTML=device.activeId&&!account?deviceGate():recoveryCode?recoveryPage():account?(!access?.canRead&&view!=='documents'?pendingShell():accountShell()):authPage();if(account&&view==='reader'&&!recoveryCode&&access?.canRead)loadReader();refreshDirectory();if(view==='bv'&&account&&access?.canRead&&(!bvData||bvData.accountId!==account.id||bvData.trash!==bvTrash)&&!bvLoading)loadBv();if(view==='site-admin'&&account&&access?.kind==='password'&&!noticeState?.draft&&!noticeLoading)refreshNotices();if(view==='documents'&&account&&(!docState||docState.accountId!==account.id||docState.trash!==docTrash)&&!docLoading)loadDocuments();document.title=!account?`${authView==='register'?'Zugang anfragen':authView==='recover'?'Zugang wiederherstellen':'Anmelden'} · aushang.`:`${view==='reader'?(catalog.find(l=>l.id===readerId)?.short||'Gesetz'):view==='bv'?'Betriebsvereinbarungen':view==='site-admin'?'Werkangaben verwalten':view==='site'?'Bekanntmachungen':view==='documents'?'Firmendokumente':view==='account'?'Mein Zugang':directoryHeading()[0]} · aushang.`;}
function navigate(next,options={}){const allowed=['aushang','collection','favorites','account','documents','site','site-admin','bv','search',...Object.keys(topicLabels)];if(!allowed.includes(next))next='aushang';if(!account){authView='login';view='aushang';render();return;}if(next==='site-admin'&&access?.kind!=='password')next='site';if(next!==view){noticeDirty=false;query='';category='';letter='';}view=next;authView='login';signupDraft=null;readerToken++;if(options.history!==false)history.pushState(null,'','#'+(next==='collection'?'alle-gesetze':next));render();window.scrollTo({top:0,behavior:'instant'});}
function focusLogin(){authView='login';$('#access-panel')?.scrollIntoView({behavior:'smooth',block:'center'});$('#login-form input[name=username]')?.focus();}
async function openLaw(id){const entry=catalog.find(x=>x.id===id);if(!entry)return;if(!entry.hosted){window.open(entry.url,'_blank','noopener,noreferrer');return;}if(!account||!access?.canRead){toast('Für die hinterlegte Textfassung bitte mit Ihrem freigeschalteten Firmenzugang anmelden.');authView='login';render();focusLogin();return;}lastCollectionView=view==='reader'?lastCollectionView:view;readerId=id;view='reader';history.pushState(null,'','#gesetz/'+id);render();window.scrollTo({top:0,behavior:'instant'});}
function readerShell(){const l=catalog.find(x=>x.id===readerId);if(!l)return directoryPage();return `<div class="reader-top"><button class="button" data-view="${lastCollectionView}">← Zurück zur Übersicht</button><div><button class="button" data-action="font">A− / A+</button><button class="button" data-action="print">${icon('print')}Drucken</button><button class="button" data-favorite="${l.id}" aria-pressed="${favorites.includes(l.id)}">${icon('bookmark')}${favorites.includes(l.id)?'Gemerkt':'Merken'}</button></div></div><div class="reader-heading"><div class="breadcrumb">Gesetzessammlung / ${esc(l.short)}</div><h1>${esc(l.title)}</h1><p>${esc(l.description||'')}</p></div><details class="reader-info"><summary>Bekanntmachung und Anwendbarkeit</summary>${(l.noticeRules||[]).length?l.noticeRules.map(r=>`<h3>${esc(r.basis)}</h3><p>${esc(r.trigger)}</p><p>${esc(r.requiredContent)}</p><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Rechtsgrundlage</a>`).join(''):`<p>Die Aufnahme in die Sammlung begründet keine allgemeine Pflicht zum Aushang dieses gesamten Textes. Die konkrete Anwendbarkeit richtet sich nach der gesetzlichen Vorschrift und den Verhältnissen des Betriebs.</p><a href="${esc(l.basisUrl||l.url)}" target="_blank" rel="noopener noreferrer">Offizielle Rechtsquelle</a>`}</details><div id="reader-content"><p class="reader-loading">Gesetzestext wird geöffnet …</p></div>`;}
function collection(){return directoryPage();}
function favoritePage(){return directoryPage();}
async function setFavorite(id){if(!account||!access?.canRead){toast('Zum Speichern von Favoriten bitte anmelden.');focusLogin();return;}if(saving)return;saving=true;try{const next=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];favorites=(await api('/api/favorites','PUT',{favorites:next})).favorites;render();toast(favorites.includes(id)?'Favorit gespeichert.':'Favorit entfernt.');}catch(e){toast(e.message);}finally{saving=false;}}
function routePortal(){let h;try{h=decodeURIComponent(location.hash.slice(1));}catch{h='';}if(['privacy','imprint','terms','updates'].includes(h)){legalPage(h);return;}if(h==='anmelden'){account=null;access=null;clearPortalState();authView='login';view='aushang';render();focusLogin();return;}if(!account){authView='login';view='aushang';render();return;}if(h.startsWith('gesetz/')){openLaw(h.slice(7));return;}navigate(h==='alle-gesetze'?'collection':!h||h==='home'?'aushang':h,{history:false});}
function fileSize(n){return n>=1024*1024?(n/1024/1024).toLocaleString('de-DE',{maximumFractionDigits:1})+' MB':Math.max(1,Math.round(n/1024))+' KB';}
function documentsPage(){
 const heading='<div class="page-heading"><div class="breadcrumb">Mein Unternehmen / Dokumente</div><h1>Firmendokumente</h1><p>Betriebsvereinbarungen, Unternehmensrichtlinien und eigene Betriebsanweisungen. Freiwillig und auf Ihren Standortzugang begrenzt.</p></div>';
 if(!account)return heading+'<section class="empty document-intro"><h2>Ihr Unternehmen entscheidet, was hier steht.</h2><p>Dieser Bereich ist optional und anfangs deaktiviert. Die Zugangsverwaltung kann eigene PDF- und DOCX-Dateien hinterlegen und für die freigeschalteten Firmencomputer veröffentlichen.</p><button class="button primary" data-action="sign-in">Mit Firmenzugang anmelden</button></section>';
 if(!docState||docState.accountId!==account.id)return heading+'<p class="loading-line">Dokumente werden geladen …</p>';
 if(docState.error)return heading+`<section class="empty"><h2>Dokumente momentan nicht erreichbar</h2><p>${esc(docState.error)}</p><button class="button" data-doc-action="reload">Erneut laden</button></section>`;
 if(!docState.enabled)return heading+`<section class="empty document-intro"><h2>Der Dokumentenbereich ist deaktiviert.</h2><p>${docState.canManage?'Aktivieren Sie ihn nur, wenn Sie eigene Unterlagen für diesen Standort bereitstellen möchten. Ohne Aktivierung wird nichts hochgeladen.':'Für diesen Standort sind keine Firmendokumente freigeschaltet.'}</p>${docState.canManage?'<button class="button primary" data-doc-action="enable">Optionalen Bereich aktivieren</button>':''}</section>`;
 const rows=(docState.documents||[]).filter(d=>!query||fold(d.title+' '+d.category+' '+d.version).includes(fold(query))).sort(sortTitle);
 return heading+`<div class="documents-toolbar"><nav aria-label="Dokumentansicht"><button data-doc-action="active" class="${!docTrash?'selected':''}">Dokumente</button>${docState.canManage?`<button data-doc-action="trash" class="${docTrash?'selected':''}">Papierkorb</button>`:''}</nav>${docState.canManage&&access?.canRead&&!docTrash?'<button class="button primary" data-doc-action="upload">Dokument hinzufügen</button>':''}</div>${docState.canManage?`<div class="document-storage"><span>${fileSize(docState.usage?.bytes||0)} von 100 MB · PDF / DOCX bis 10 MB je Datei</span><button class="text-button" data-doc-action="disable">Bereich ausblenden</button></div>`:''}${!access?.canRead?'<div class="context-note">Ihre Lizenz ist momentan nicht aktiv. Sie können Ihre bereits gespeicherten Unterlagen weiterhin herunterladen und verwalten; neue Uploads erfordern eine Freischaltung.</div>':''}<label class="document-search field">Dokumente filtern<input id="document-search" type="search" placeholder="Titel oder Dokumentart" value="${esc(query)}"></label><div id="document-list">${documentRows(rows)}</div><p class="directory-footnote">Entwürfe sind nur in der Passwortverwaltung sichtbar. Freigegebene Dokumente stehen den autorisierten Geräten desselben Standortzugangs zur Verfügung. Die digitale Ablage ersetzt nicht automatisch jede gesetzlich vorgeschriebene Bekanntmachungsform.</p>`;
}
function documentRows(rows){return rows.length?`<div class="document-list">${rows.map(d=>`<article class="document-row"><span class="file-kind">${d.mime==='application/pdf'?'PDF':'DOCX'}</span><div><h3>${esc(d.title)}</h3><p>${esc(d.category)}${d.version?' · Version '+esc(d.version):''}${d.effectiveDate?' · Stand '+date(d.effectiveDate):''}</p><small>${esc(d.originalName)} · ${fileSize(d.size)}</small><span class="publication-state ${d.published?'published':''}">${d.deletedAt?'Papierkorb':d.published?'Für Firmencomputer freigegeben':'Entwurf · nur Verwaltung'}</span></div><div class="document-actions">${d.deletedAt?`<button class="button small" data-doc-action="restore" data-id="${d.id}">Wiederherstellen</button><button class="text-button danger" data-doc-action="permanent" data-id="${d.id}">Endgültig löschen</button>`:`<a class="button small" href="/api/documents/${d.id}/download">Herunterladen</a>${docState.canManage?`<button class="text-button" data-doc-action="edit" data-id="${d.id}">Bearbeiten / Freigeben</button><button class="text-button" data-doc-action="delete" data-id="${d.id}">In den Papierkorb</button>`:''}`}</div></article>`).join('')}</div>`:`<section class="empty"><h2>${docTrash?'Der Papierkorb ist leer.':query?'Keine passenden Dokumente.':'Noch keine Dokumente vorhanden.'}</h2><p>${docTrash?'Gelöschte Dokumente können hier wiederhergestellt oder nach Bestätigung endgültig entfernt werden.':docState.canManage?'Fügen Sie eine Betriebsvereinbarung oder Richtlinie als PDF oder DOCX hinzu.':'Die Zugangsverwaltung hat noch keine Unterlagen für Firmencomputer veröffentlicht.'}</p></section>`;}
async function loadDocuments(){
 if(!account||docLoading)return;const id=account.id,token=++documentRequestToken;docLoading=true;
 try{const data=await api('/api/documents'+(docTrash?'?trash=1':''));if(token!==documentRequestToken||account?.id!==id)return;docState={...data,accountId:id,trash:docTrash};}
 catch(e){if(token===documentRequestToken&&account?.id===id)docState={accountId:id,trash:docTrash,error:e.message};}
 finally{if(token===documentRequestToken){docLoading=false;if(view==='documents')render();}}
}
function documentForm(id){const d=id?docState.documents.find(x=>x.id===id):null;if(id&&!d)return;show(`<h2 id="dialog-title" class="dialog-title">${d?'Dokument bearbeiten':'Firmendokument hinzufügen'}</h2><form id="document-form" data-id="${d?.id||''}"><label class="field">Titel<input name="title" value="${esc(d?.title||'')}" required maxlength="180"></label><label class="field">Dokumentart<select name="category">${['Betriebsvereinbarung','Unternehmensrichtlinie','Betriebsanweisung','Sonstiges'].map(c=>`<option ${d?.category===c?'selected':''}>${c}</option>`).join('')}</select></label><div class="form-grid"><label class="field">Version (optional)<input name="version" value="${esc(d?.version||'')}" maxlength="40" placeholder="z. B. 1.0"></label><label class="field">Dokumentstand (optional)<input type="date" name="effectiveDate" value="${esc(d?.effectiveDate||'')}"></label></div>${!d?'<label class="file-upload-label">PDF oder DOCX auswählen<input type="file" name="file" accept=".pdf,.docx" required><small>Maximal 10 MB. Die Datei wird im Dokumentenspeicher dieses Standortzugangs abgelegt.</small></label>':`<p class="legal-note">Datei: ${esc(d.originalName)}. Für einen anderen Dateiinhalt laden Sie bitte eine neue Dokumentversion hoch.</p>`}<label class="check-label publication-choice"><input type="checkbox" name="published" ${d?.published?'checked':''}>Auf den freigeschalteten Firmencomputern dieses Zugangs anzeigen</label><p class="legal-note">Ohne Freigabe bleibt das Dokument ein Entwurf und ist nur nach Anmeldung mit dem Verwaltungspasswort sichtbar.</p>${!d?'<label class="check-label"><input type="checkbox" name="authorized" required>Ich bin berechtigt, diese Datei für diesen Standort bereitzustellen.</label>':''}<div class="form-error" id="document-error" role="alert"></div><div class="form-buttons"><button class="button primary" type="submit">${d?'Änderungen speichern':'Dokument hochladen'}</button><button class="button" type="button" data-doc-action="close">Abbrechen</button></div></form>`);}
async function documentAction(action,b){
 if(action==='close'){$('#dialog').close();return;}
 if(action==='upload'){documentForm();return;}
 if(action==='edit'){documentForm(b.dataset.id);return;}
 if(action==='permanent'){const d=docState.documents.find(x=>x.id===b.dataset.id);if(!d)return;show(`<h2 id="dialog-title" class="dialog-title">Dokument endgültig löschen?</h2><p><strong>${esc(d.title)}</strong> wird aus dem Dokumentenspeicher entfernt. Diese Aktion kann nicht rückgängig gemacht werden.</p><div class="form-buttons"><button class="button danger-button" data-doc-action="confirm-permanent" data-id="${d.id}">Endgültig löschen</button><button class="button" data-doc-action="close">Abbrechen</button></div>`);return;}
 b.disabled=true;try{
  if(action==='enable'||action==='disable')await api('/api/documents/settings','PUT',{enabled:action==='enable'});
  if(action==='active'||action==='trash'){docTrash=action==='trash';query='';}
  if(action==='delete')await api('/api/documents/'+b.dataset.id,'DELETE');
  if(action==='restore')await api('/api/documents/'+b.dataset.id+'/restore','POST',{});
  if(action==='confirm-permanent'){await api('/api/documents/'+b.dataset.id+'/permanent','DELETE',{confirm:'PERMANENT_DELETE'});$('#dialog').close();}
  docState=null;await loadDocuments();
 }catch(e){toast(e.message);}finally{if(b.isConnected)b.disabled=false;}
}
document.addEventListener('input',e=>{if(e.target.id==='law-search'){query=e.target.value;letter='';refreshDirectory();}if(e.target.id==='document-search'){query=e.target.value;const rows=(docState?.documents||[]).filter(d=>!query||fold(d.title+' '+d.category+' '+d.version).includes(fold(query))).sort(sortTitle);$('#document-list').innerHTML=documentRows(rows);}});
document.addEventListener('submit',async e=>{
 if(e.target.id==='global-library-search'){e.preventDefault();const term=$('#global-law-search').value;query='';navigate('search');query=term;render();return;}
 if(e.target.id==='library-search'){e.preventDefault();query=$('#law-search').value;refreshDirectory();return;}
 if(e.target.id!=='document-form')return;e.preventDefault();const form=e.target,button=form.querySelector('button[type=submit]');button.disabled=true;$('#document-error').textContent='';
 try{const data=new FormData(form);data.set('published',form.elements.published.checked?'true':'false');
  if(form.dataset.id)await api('/api/documents/'+form.dataset.id,'PATCH',{title:data.get('title'),category:data.get('category'),version:data.get('version'),effectiveDate:data.get('effectiveDate'),published:data.get('published')==='true'});
  else{const file=data.get('file');if(!file||file.size>10*1024*1024)throw Error('Bitte eine PDF- oder DOCX-Datei bis 10 MB auswählen.');const response=await fetch('/api/documents',{method:'POST',credentials:'same-origin',body:data,cache:'no-store'});const result=await response.json();if(!response.ok){if(response.status===401){account=null;access=null;docState=null;render();}throw Error(result.error||'Upload fehlgeschlagen.');}}
  $('#dialog').close();docState=null;await loadDocuments();toast('Firmendokument gespeichert.');
 }catch(err){if($('#document-error'))$('#document-error').textContent=err.message;else toast(err.message);}finally{if(button.isConnected)button.disabled=false;}
});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.filter!==undefined){category=b.dataset.filter;letter='';render();}
 if(b.dataset.alpha!==undefined){letter=b.dataset.alpha;refreshDirectory();}
 if(b.dataset.action==='clear-search'){query='';category='';letter='';render();}
 if(b.dataset.action==='sign-in'){authView='login';render();focusLogin();}
 if(b.dataset.action==='show-password'){const input=$('#login-password'),visible=input.type==='password';input.type=visible?'text':'password';b.textContent=visible?'Verbergen':'Anzeigen';b.setAttribute('aria-label',visible?'Passwort verbergen':'Passwort anzeigen');}
 if(b.dataset.docAction)documentAction(b.dataset.docAction,b);
});

function noticeDefinitions(){return noticeState?.definitions||[];}
function publishedNotice(id){return noticeState?.published?.[id]||{status:'unconfirmed',text:''};}
function noticeLabel(n){return n.status==='not_applicable'?'Vom Betrieb als nicht zutreffend eingeordnet':n.status==='unconfirmed'?'Anwendbarkeit noch nicht bestätigt':n.text?'Betriebliche Angabe hinterlegt':'Noch nicht hinterlegt';}
function noticeList(){if(!noticeState)return '<p class="mini-note">Werkangaben werden geladen …</p>';return noticeDefinitions().map(d=>{const n=publishedNotice(d.id);return `<button class="werk-notice ${n.status==='applicable'&&!n.text?'missing':''}" data-notice="${esc(d.id)}"><span>${esc(d.title)}</span><small>${esc(noticeLabel(n))}</small>${icon('arrow')}</button>`;}).join('')+`<p class="notice-dateline">${noticeState.publishedAt?'Vom Betrieb freigegeben: '+date(noticeState.publishedAt*1000):'Es wurden noch keine Werkangaben veröffentlicht.'}</p>`;}
function homeShortcuts(){const saved=catalog.filter(l=>favorites.includes(l.id)).slice(0,4);return `<section class="home-shortcuts" aria-label="Schnellzugriff"><div class="shortcut-label">FÜR DIESES WERK GEMERKT</div><div class="saved-titles">${saved.length?saved.map(l=>`<button data-law="${esc(l.id)}" title="${esc(l.title)}">${esc(l.short)} ${icon('arrow')}</button>`).join(''):'<span>Mit dem Lesezeichen neben einem Titel legen Sie Ihre Favoriten an.</span>'}</div><button class="text-button" data-view="favorites">Alle Favoriten ${icon('arrow')}</button></section>`;}
async function refreshNotices(){if(!account||!access?.canRead||noticeLoading||(view==='site-admin'&&noticeDirty))return;const id=account.id,token=++noticeToken;noticeLoading=true;try{const data=await api('/api/site-notices');if(token!==noticeToken||account?.id!==id)return;noticeState={...data,accountId:id};if(view==='site-admin'||view==='site')render();else if($('#werk-notices'))$('#werk-notices').innerHTML=noticeList();}catch(e){toast(e.message);}finally{if(token===noticeToken)noticeLoading=false;}}
function noticeDetail(id){const d=noticeDefinitions().find(x=>x.id===id);if(!d)return;const n=publishedNotice(id);show(`<h2 id="dialog-title" class="dialog-title">${esc(d.title)}</h2><p class="notice-status">${esc(noticeLabel(n))}</p>${n.text&&n.status!=='unconfirmed'?`<div class="notice-body">${esc(n.text).replace(/\n/g,'<br>')}</div>`:'<p>Hier ist noch keine entsprechende betriebliche Information veröffentlicht. Bitte die zuständige betriebliche Verwaltung ansprechen.</p>'}<p class="legal-note">${esc(d.condition)}</p><a href="${esc(d.url)}" target="_blank" rel="noopener noreferrer">${esc(d.basis)}</a>${id==='agreements'?'<p><button class="button" data-kiosk-action="open-bv">Zu den BV-Verknüpfungen</button></p>':''}`);}
function sitePage(){return `<div class="page-heading"><div class="breadcrumb">IHR WERK / BEKANNTMACHUNGEN</div><h1>Betriebliche Bekanntmachungen</h1><p>Die hier veröffentlichten Angaben stammen von Ihrem Unternehmen. Sie ergänzen die Gesetzestexte.</p></div><div class="published-notices">${noticeDefinitions().map(d=>{const n=publishedNotice(d.id);return `<section><div class="notice-section-heading"><h2>${esc(d.title)}</h2><small>${esc(noticeLabel(n))}</small></div>${n.text&&n.status!=='unconfirmed'?`<div class="notice-body">${esc(n.text).replace(/\n/g,'<br>')}</div>`:'<p class="muted">Noch keine entsprechende betriebliche Angabe veröffentlicht.</p>'}<p class="legal-note">${esc(d.condition)}</p><a href="${esc(d.url)}" target="_blank" rel="noopener noreferrer">${esc(d.basis)}</a></section>`;}).join('')}</div><div class="device-actions"><button class="button" data-kiosk-action="reload-notices">Angaben neu laden</button><button class="button" data-view="documents">Firmendokumente öffnen</button>${access?.kind==='password'?'<button class="button primary" data-view="site-admin">Werkangaben verwalten</button>':''}</div><p class="directory-footnote">Der Veröffentlichungsstand dokumentiert die betriebliche Freigabe; er ist kein Nachweis einer vollständigen rechtlichen Prüfung.</p>`;}
function siteEditor(){if(access?.kind!=='password')return sitePage();if(!noticeState?.draft)return '<p class="loading-line">Werkangaben werden geladen …</p>';return `<div class="page-heading"><div class="breadcrumb">VERWALTUNG / WERKANGABEN</div><h1>Werkangaben verwalten</h1><p>Nur freigegebene Angaben erscheinen auf den Firmencomputern dieses Standorts. Entwürfe bleiben in der Passwortverwaltung.</p></div><form id="site-notices-form" data-revision="${noticeState.revision}">${noticeDefinitions().map(d=>{const n=noticeState.draft[d.id];return `<fieldset class="notice-edit"><legend>${esc(d.title)}</legend><p>${esc(d.condition)}</p><a class="notice-basis" href="${esc(d.url)}" target="_blank" rel="noopener noreferrer">${esc(d.basis)}</a>${d.always?'<input type="hidden" name="'+d.id+'-status" value="applicable"><p class="mini-note">Betrieblich bekanntzumachen.</p>':`<label class="field">Betriebliche Einordnung<select name="${d.id}-status"><option value="unconfirmed" ${n.status==='unconfirmed'?'selected':''}>Noch nicht geprüft</option><option value="applicable" ${n.status==='applicable'?'selected':''}>Für dieses Werk anwendbar</option><option value="not_applicable" ${n.status==='not_applicable'?'selected':''}>Für dieses Werk nicht zutreffend</option></select></label>`}<label class="field">${d.id==='agg'?'Zuständige Stelle und erreichbarer Kontakt':d.id==='youth-authority'?'Name und Anschrift der zuständigen Behörde':d.id==='youth-hours'?'Arbeitszeiten / Pausen oder Begründung': 'Zugang zu den geltenden Volltexten oder Begründung'}<textarea name="${d.id}-text" rows="5" maxlength="2500">${esc(n.text)}</textarea></label></fieldset>`;}).join('')}<div class="form-error" id="notice-error" role="alert"></div><button class="button primary" type="submit">Entwurf speichern</button></form><section class="publish-panel"><h2>Für Firmencomputer veröffentlichen</h2><p>Speichern Sie zuerst den Entwurf. Vor der Veröffentlichung die Angaben sachlich prüfen und die betriebliche Freigabe einholen.</p><label class="check-label"><input id="notice-authorized" type="checkbox">Ich bin zur Veröffentlichung für dieses Werk berechtigt und habe die Angaben betrieblich freigegeben.</label><button class="button" data-kiosk-action="publish-notices">Gespeicherten Entwurf veröffentlichen</button></section><section class="backup-guidance"><h2>Zugänglichkeit im Betrieb</h2><p>Der gemeinsame Computer muss allen Beschäftigten und allen Schichten ohne zusätzliche Anmeldung zugänglich sein. Für Geräte- oder Internetausfälle einen geeigneten Papier- oder lokalen PDF-Ersatz bereithalten und regelmäßig aktualisieren. Dieser Onlinezugang erstellt keinen automatischen Offline-Ersatz.</p></section>`;}
document.addEventListener('input',e=>{if(e.target.closest('#site-notices-form'))noticeDirty=true;});
document.addEventListener('change',e=>{if(e.target.closest('#site-notices-form'))noticeDirty=true;});
document.addEventListener('submit',async e=>{if(e.target.id!=='site-notices-form')return;e.preventDefault();const form=e.target,data=new FormData(form),button=form.querySelector('button[type=submit]');button.disabled=true;$('#notice-error').textContent='';try{const notices=Object.fromEntries(noticeDefinitions().map(d=>[d.id,{status:data.get(d.id+'-status'),text:data.get(d.id+'-text')}]));const result=await api('/api/site-notices','PUT',{revision:Number(form.dataset.revision),notices});noticeState={...result,accountId:account.id};noticeDirty=false;render();toast('Entwurf gespeichert. Die Firmencomputer sehen weiterhin die zuletzt veröffentlichte Fassung.');}catch(err){$('#notice-error').textContent=err.message;}finally{if(button.isConnected)button.disabled=false;}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.notice){noticeDetail(b.dataset.notice);return;}const action=b.dataset.kioskAction;if(!action)return;if(action==='fullscreen'){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Vollbild kann in diesem Browser nicht geöffnet werden.');}}if(action==='reload-notices')refreshNotices();if(action==='open-bv'){$('#dialog').close();navigate('bv');}if(action==='open-documents'){$('#dialog').close();navigate('documents');}if(action==='access-help')show('<h2 id="dialog-title" class="dialog-title">Gesetze im Betrieb einsehen</h2><p>Die Übersicht gehört zum oben genannten Werk. Gesetzestitel öffnen die hinterlegte Fassung oder eine gekennzeichnete Originalquelle. Mit dem Lesezeichen werden Titel für dieses Werk gemerkt.</p><p>Für die Nutzung am gemeinsamen Firmencomputer benötigen Beschäftigte keine persönliche Anmeldung. Die Verwaltung der Werkangaben und Dateien bleibt mit dem Passwort geschützt.</p><p>Bei fehlendem Internet, nicht verfügbaren Texten oder unzugänglichem Computer bitte die betriebliche Verwaltung informieren und den bereitgehaltenen Ersatz nutzen.</p>');if(action==='publish-notices'){if(noticeDirty){toast('Bitte zuerst Ihre Änderungen als Entwurf speichern.');return;}if(!$('#notice-authorized')?.checked){toast('Bitte zuerst die betriebliche Freigabe bestätigen.');return;}b.disabled=true;try{const result=await api('/api/site-notices/publish','POST',{revision:noticeState.revision,authorized:true});noticeState={...result,accountId:account.id};render();toast('Werkangaben für die Firmencomputer veröffentlicht.');}catch(err){toast(err.message);}finally{if(b.isConnected)b.disabled=false;}}});

function bvPage(){
 const heading='<div class="page-heading"><div class="breadcrumb">IHR WERK / VEREINBARUNGEN</div><h1>Betriebsvereinbarungen</h1><p>Die Vereinbarungen Ihres Standorts als Links. Die Dateien bleiben im Firmensystem.</p></div>';
 if(!bvData||bvData.accountId!==account.id)return heading+'<p class="loading-line">BV-Bereich wird geladen …</p>';
 if(bvData.error)return heading+`<p>${esc(bvData.error)}</p><button class="button" data-bv-action="reload">Erneut laden</button>`;
 if(!bvData.canManage&&!bvData.enabled)return heading+'<section class="empty"><h2>Noch keine Betriebsvereinbarungen bereitgestellt</h2><p>Die Zugangsverwaltung kann hier Links für dieses Werk hinzufügen.</p></section>';
 const rows=(bvData.links||[]).filter(l=>!query||fold(l.title+' '+l.version).includes(fold(query)));
 return heading+`${bvData.canManage?`<div class="documents-toolbar"><nav><button data-bv-action="active" class="${!bvTrash?'selected':''}">Verknüpfungen</button><button data-bv-action="trash" class="${bvTrash?'selected':''}">Papierkorb</button></nav>${bvData.enabled&&!bvTrash?'<button class="button primary" data-bv-action="new">BV-Link hinzufügen</button>':''}</div><details class="bv-settings" ${!bvData.enabled?'open':''}><summary>BV-Bereich verwalten</summary><form id="bv-settings-form"><label class="check-label"><input name="enabled" type="checkbox" ${bvData.enabled?'checked':''}>BV-Verknüpfungen für dieses Werk anzeigen</label><div id="bv-settings-error" class="form-error" role="alert"></div><button class="button" type="submit">Einstellungen speichern</button></form></details>`:''}<label class="field document-search">BV-Titel filtern<input id="bv-search" type="search" placeholder="Titel oder Version" value="${esc(query)}"></label><div id="bv-list">${bvRows(rows)}</div><p class="directory-footnote">Die Links werden nur innerhalb dieses Werkzugangs angezeigt. Wer das verlinkte Dokument öffnen darf, bestimmt das Firmensystem. Verwenden Sie dafür passend berechtigte Firmenlinks.</p>`;
}
function bvRows(rows){return rows.length?rows.map(l=>`<article class="document-row"><span class="file-kind">LINK</span><div><h3>${esc(l.title)}</h3><p>${l.version?'Version '+esc(l.version):'Betriebsvereinbarung'}${bvData.canManage?' · '+(l.published?'Freigegeben':'Entwurf'):''}</p><small>${esc(new URL(l.url).hostname)}</small></div><div class="document-actions">${l.deletedAt?`<button class="button small" data-bv-action="restore" data-id="${l.id}">Wiederherstellen</button>`:`<a class="button small" href="/api/bv-links/${l.id}/open" target="_blank" rel="noopener noreferrer">Öffnen ${icon('external')}</a><button class="text-button" data-bv-action="copy" data-id="${l.id}">Link kopieren</button>${bvData.canManage?`<button class="text-button" data-bv-action="edit" data-id="${l.id}">Bearbeiten</button><button class="text-button" data-bv-action="delete" data-id="${l.id}">In den Papierkorb</button>`:''}`}</div></article>`).join(''):'<section class="empty"><h2>Keine Verknüpfungen vorhanden</h2><p>Hier erscheinen die für diesen Standort bereitgestellten BV-Links.</p></section>';}
async function loadBv(){if(!account||!access?.canRead||bvLoading)return;const id=account.id,token=++bvToken;bvLoading=true;try{const result=await api('/api/bv-links'+(bvTrash?'?trash=1':''));if(token!==bvToken||account?.id!==id)return;bvData={...result,accountId:id,trash:bvTrash};}catch(e){if(token===bvToken&&account?.id===id)bvData={accountId:id,trash:bvTrash,error:e.message};}finally{if(token===bvToken){bvLoading=false;if(view==='bv')render();}}}
function bvLinkForm(id){const l=bvData.links.find(x=>x.id===id)||{title:'',url:'',version:'',published:0};show(`<h2 id="dialog-title" class="dialog-title">${id?'BV-Link bearbeiten':'BV-Link hinzufügen'}</h2><form id="bv-link-form" data-id="${id||''}"><label class="field">Titel<input name="title" required maxlength="180" value="${esc(l.title)}"></label><label class="field">Link zur Betriebsvereinbarung<input name="url" type="url" required maxlength="2000" placeholder="https://…" value="${esc(l.url)}"><small>Nur der Link wird gespeichert. Bitte keine Passwörter oder Zugangsschlüssel einfügen.</small></label><label class="field">Version / Stand<input name="version" maxlength="40" value="${esc(l.version)}"></label><label class="check-label"><input name="published" type="checkbox" ${l.published?'checked':''}>Im Werkzugang veröffentlichen</label><p class="legal-note">Der Link ändert keine Berechtigungen im Firmensystem. Prüfen Sie vor dem Veröffentlichen, wer das Original öffnen darf.</p><div id="bv-link-error" class="form-error" role="alert"></div><button class="button primary" type="submit">Speichern</button></form>`);}
document.addEventListener('input',e=>{if(e.target.id==='bv-search'){query=e.target.value;$('#bv-list').innerHTML=bvRows((bvData.links||[]).filter(l=>!query||fold(l.title+' '+l.version).includes(fold(query))));}});
document.addEventListener('submit',async e=>{if(!['bv-settings-form','bv-link-form'].includes(e.target.id))return;e.preventDefault();const f=e.target,data=Object.fromEntries(new FormData(f)),button=f.querySelector('button[type=submit]'),errorNode=$(f.id==='bv-settings-form'?'#bv-settings-error':'#bv-link-error');errorNode.textContent='';button.disabled=true;try{if(f.id==='bv-settings-form')await api('/api/bv-links/settings','PUT',{enabled:data.enabled==='on'});else{await api('/api/bv-links'+(f.dataset.id?'/'+f.dataset.id:''),f.dataset.id?'PATCH':'POST',{title:data.title,url:data.url,version:data.version,published:data.published==='on'});$('#dialog').close();}bvData=null;await loadBv();toast(f.id==='bv-link-form'?'BV-Link gespeichert.':'BV-Einstellungen gespeichert.');}catch(err){if(errorNode?.isConnected!==false)errorNode.textContent=err.message;else toast(err.message);}finally{if(button.isConnected)button.disabled=false;}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b?.dataset.bvAction)return;const action=b.dataset.bvAction;if(action==='new'||action==='edit'){bvLinkForm(b.dataset.id);return;}b.disabled=true;try{if(action==='copy'){const l=bvData.links.find(x=>x.id===b.dataset.id);if(!l)return;if(!navigator.clipboard?.writeText){show(`<h2 id="dialog-title" class="dialog-title">Firmenlink teilen</h2><p>Markieren und kopieren Sie den Link:</p><input aria-label="BV-Link" readonly value="${esc(l.url)}">`);return;}await navigator.clipboard.writeText(l.url);toast('Firmenlink kopiert. Die Berechtigungen des Zielsystems gelten weiterhin.');return;}if(action==='active'||action==='trash'){bvTrash=action==='trash';query='';}if(action==='delete')await api('/api/bv-links/'+b.dataset.id,'DELETE');if(action==='restore')await api('/api/bv-links/'+b.dataset.id+'/restore','POST',{});bvData=null;await loadBv();}catch(err){toast(err.message);}finally{if(b.isConnected)b.disabled=false;}});

window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
window.addEventListener('hashchange',routePortal);window.addEventListener('popstate',routePortal);
(async()=>{try{localStorage.removeItem('aushang-demo-v1');}catch{}if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js',{scope:'/'}).catch(()=>{});try{const h=location.hash.slice(1),allowed=['aushang','collection','favorites','account','documents','site','site-admin','bv','search',...Object.keys(topicLabels)];view=h==='alle-gesetze'?'collection':allowed.includes(h)?h:'aushang';if(device.activeId){await openDevice();return;}await hydrateAccount();if(h.startsWith('gesetz/')&&account&&access?.canRead)await openLaw(h.slice(7));else if(['privacy','imprint','terms','updates'].includes(h))legalPage(h);}catch{render();toast('Der Dienst ist momentan nicht erreichbar. Bitte später erneut versuchen.');}})();
})();
